-- Review-gated Ministry of Tribal Affairs, PMJVM, VCF-ST and NSTFDC routes.
-- This seed mirrors 20260908140000_catalog_tribal_livelihood_nstfdc_current_evidence.sql for ordered local provisioning.

do $$
declare
  item jsonb;
  authority_id uuid;
  seed_opportunity_id uuid;
  version_id uuid;
begin
  for item in
    select value from jsonb_array_elements($records$[
      {"slug":"pmjvm-tribal-value-chain","name":"Pradhan Mantri Janjatiya Vikas Mission (PMJVM)","type":"tribal_value_chain_support","status":"active","authority":"Ministry of Tribal Affairs - PMJVM","authority_url":"https://tribal.gov.in/","canonical_url":"https://tribal.gov.in/Livelihood.aspx","source_url":"https://tribal.gov.in/Livelihood.aspx","source_kind":"ministry","source_title":"Ministry of Tribal Affairs livelihood schemes","source_anchor":"PMJVM merger of MFP value-chain and tribal-product marketing support; tribal entrepreneurship and livelihood objectives; TRIFED implementation","summary":"Central support for tribal producer groups, Van Dhan activities and tribal-product value chains, with implementation through State systems and TRIFED.","objective":"Strengthen tribal entrepreneurship and livelihood opportunities through MFP, farm and non-farm value addition, producer groups and market linkages.","legal_basis":"Ministry of Tribal Affairs PMJVM page and official TRIFED Van Dhan material; current scheme guideline, State proposal and continuation status control the live case.","eligibility":{"entity_types":["tribal_producer_group","tribal_shg","vdvk","tribal_cooperative","state_implementing_agency"],"lifecycle_stages":["starting","operating","expanding"],"industries":["minor_forest_produce","agriculture_and_allied","food_processing","handicrafts","tribal_products","rural_enterprise"],"locations":["India","tribal_district","scheduled_area"],"conditions":["activity must serve eligible Scheduled Tribe communities and a tribal value chain","route may involve VDVK/producer groups, State Government proposals and TRIFED","support is project and implementation-route dependent, not a direct universal founder grant","MFP, farm/non-farm produce, value addition, procurement and market linkage must be evidenced","FY 2026-27 continuation, local allocation and current operational guideline require verification"],"thresholds":{"benefit_amount":"not stated as a universal per-applicant amount","implementation_route":"state_or_trifed"},"unknown_handling":"needs_information"},"exclusions":["not a universal cash entitlement for every tribal business","State proposal, VDVK/producer-group structure and local implementation determine access","PMJVM support cannot be combined with unrelated grants without checking the applicable guideline","current continuation and component-level ceilings must be re-verified before publication"],"application":{"portal":"https://tribal.gov.in/Livelihood.aspx","route":"Identify the applicable State Tribal Department, VDVK/producer-group or TRIFED route, prepare the value-chain proposal and follow the current State or implementing-agency process.","selection":"State and implementing agencies assess community, activity, value-chain, implementation and monitoring conditions; UdyamVeda cannot approve a project.","fees":"No universal applicant fee is stated in the reviewed sources; local proposal and implementation requirements must be confirmed.","applicant_note":"UdyamVeda may explain the route and prepare a proposal checklist, but must not represent itself as the Ministry or TRIFED."},"fine_print":{"implementation":"The Ministry describes PMJVM as a merger of earlier MFP and tribal-product marketing schemes, with TRIFED as nodal implementing agency.","support_model":"Support is routed through State systems, VDVKs, producer groups and value-chain interventions; it is not automatically paid to an individual founder.","current_boundary":"The livelihood page describes a 2021-22 to 2025-26 vision while the FY 2026-27 financial summary shows a current allocation line; human review must reconcile the continuation, guideline and component terms.","review_note":"Verify current year, State coverage, proposal route, eligible products, infrastructure/value-addition support, procurement, market linkage, reporting and amendment history before publication."},"benefit_summary":{"types":["grant","market_access","training"],"summary":"Project and value-chain support for tribal producer groups and Van Dhan activities; no universal per-founder amount is established by the reviewed sources.","separate_value_buckets":true},"benefit_type":"grant","benefit_label":"PMJVM project and tribal value-chain support; amount and route depend on approved component and State/implementing-agency proposal","amount_min":null,"amount_max":null,"percentage":null,"benefit_conditions":{"tribal_value_chain_required":true,"state_or_trifed_route_required":true,"no_universal_applicant_ceiling_published":true,"support_not_guaranteed":true},"requirement":"ST community/producer-group evidence, value-chain proposal and State/TRIFED route documentation","requirement_description":"Provide group or VDVK constitution, ST-community and beneficiary evidence, product/value-chain description, activity plan, market linkage, budget, implementation location, State/TRIFED forms and monitoring declarations.","rules":{"all":[{"field":"tribal_group_or_vdvk_verified","operator":"equals","value":true},{"field":"activity_in_tribal_value_chain","operator":"equals","value":true},{"field":"state_or_trifed_route_available","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Identify the PMJVM component","description":"Map the proposed activity to VDVK, MFP, tribal product, value addition, procurement or market-linkage support.","url":"https://tribal.gov.in/Livelihood.aspx"},{"title":"Confirm implementing route","description":"Confirm the relevant State Tribal Department, VDVK/producer group or TRIFED route and current-year availability.","url":"https://trifed.tribal.gov.in/index.php/en/pmvdy"},{"title":"Prepare the value-chain proposal","description":"Collect group, product, budget, market, infrastructure and monitoring evidence required by the current component.","url":"https://trifed.tribal.gov.in/en/non/timber/procurement"},{"title":"Submit and monitor through the authority","description":"Submit through the applicable State or TRIFED process and retain sanction, utilization and reporting records.","url":"https://tribal.gov.in/PFMS_SentionDtSchemewise2627.aspx"}],"window_type":"rolling","window_close_at":null,"window_label":"Ongoing ministry/State implementation route; current-year component calls and local deadlines must be confirmed.","window_evidence":{"source_url":"https://tribal.gov.in/PFMS_SentionDtSchemewise2627.aspx","anchor":"FY 2026-27 financial summary lists PMJVM allocation; it does not itself establish an applicant deadline."},"review_note":"Keep review-gated. Do not show a generic grant amount or individual eligibility until the current component and State route are verified."},
      {"slug":"vcf-st-tribal-startups","name":"Venture Capital Fund for Scheduled Tribes (VCF-ST)","type":"venture_capital","status":"active","authority":"Ministry of Tribal Affairs - VCF-ST","authority_url":"https://tribal.gov.in/","canonical_url":"https://tribal.gov.in/Livelihood.aspx","source_url":"https://tribal.gov.in/Livelihood.aspx","source_kind":"ministry","source_title":"Ministry of Tribal Affairs livelihood schemes","source_anchor":"VCF-ST objective to promote ST entrepreneurship and support/incubate startup ideas; IFCI VCF Ltd management","summary":"A Ministry of Tribal Affairs venture-capital route intended to promote Scheduled Tribe entrepreneurship and support or incubate startup ideas of ST youth.","objective":"Promote ST entrepreneurship through concessional venture finance and support for eligible startup ideas.","legal_basis":"Ministry of Tribal Affairs VCF-ST scheme page and Ministry-linked guideline reference; fund manager terms and current call control the live case.","eligibility":{"entity_types":["st_founder","st_led_startup","startup","innovative_enterprise"],"lifecycle_stages":["idea","starting","validating","scaling"],"industries":["technology","manufacturing","services","social_enterprise","rural_enterprise"],"locations":["India"],"conditions":["founder or controlling applicant must satisfy the current Scheduled Tribe condition","startup idea or venture must fit the current fund and investment mandate","application is managed through IFCI VCF Ltd or the currently notified fund route","investment terms, dilution, instrument, ticket size and call status require current verification","incubation, due diligence, milestones and reporting may apply"],"thresholds":{"ticket_size":"not stated on the current overview page","fund_corpus":"not an applicant benefit ceiling","founder_st_status":"required_subject_to_current_guideline"},"unknown_handling":"needs_information"},"exclusions":["not a grant or guaranteed investment","the Ministry overview does not establish a current open call, ticket size or investment instrument","investment selection and due diligence remain with the fund manager","founder status and control cannot be inferred from a generic startup profile"],"application":{"portal":"https://tribal.gov.in/Livelihood.aspx","route":"Review the current VCF-ST guideline and IFCI VCF route, prepare the startup deck, founder-status evidence, cap table and diligence material, and apply only through the notified channel.","selection":"IFCI VCF Ltd or the notified fund manager evaluates eligibility, venture quality, diligence, instrument, valuation and investment conditions; UdyamVeda cannot promise funding.","fees":"No universal applicant fee is established by the reviewed sources; fund manager terms must be checked.","applicant_note":"UdyamVeda may prepare the investment-readiness checklist but must not represent itself as IFCI VCF Ltd or submit investment documents without consent."},"fine_print":{"fund_manager":"The Ministry page identifies IFCI VCF Ltd as manager of the VCF-ST scheme.","instrument":"Current public overview does not establish whether a live case uses equity, quasi-equity, debt or another instrument; preserve the ambiguity until guideline and call review.","availability":"FY 2026-27 financial summary shows an allocation line, but allocation is not proof of an open founder application window.","review_note":"Verify current guideline, founder/ST definition, investment instrument, ticket size, dilution, valuation, incubation, call dates, fund manager forms and portfolio obligations before publication."},"benefit_summary":{"types":["venture_capital","incubation"],"summary":"Potential venture finance and startup support for eligible ST entrepreneurs; ticket size, instrument and open-call status require current fund-manager verification.","separate_value_buckets":true},"benefit_type":"venture_capital","benefit_label":"Potential VCF-ST venture finance for eligible ST-led startups; current instrument and ticket size require verification","amount_min":null,"amount_max":null,"percentage":null,"benefit_conditions":{"st_founder_condition":true,"ifci_vcf_route_required":true,"investment_not_guaranteed":true,"ticket_size_unpublished_on_overview":true},"requirement":"ST-founder evidence, startup incorporation and cap-table records, pitch deck and diligence material","requirement_description":"Provide founder/ST evidence, incorporation and ownership records, pitch deck, product/market evidence, financial model, cap table, use of funds, IP and current IFCI VCF forms.","rules":{"all":[{"field":"st_founder_status_verified","operator":"equals","value":true},{"field":"startup_or_innovative_venture_verified","operator":"equals","value":true},{"field":"ifci_vcf_application_route_available","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Confirm current VCF-ST call and mandate","description":"Check the live guideline, fund manager route, founder condition, investment instrument and ticket boundaries.","url":"https://tribal.gov.in/Livelihood.aspx"},{"title":"Prepare investment-readiness evidence","description":"Assemble founder, incorporation, ownership, product, traction, financial and use-of-funds records.","url":"https://tribal.nic.in/downloads/Livelihood/Guidelines/VCF-STGuidelines1123.pdf"},{"title":"Submit through the notified fund route","description":"Apply to IFCI VCF Ltd or the currently notified channel and complete diligence.","url":"https://tribal.gov.in/DivisionsFiles/CitizensCharter19052026.pdf"},{"title":"Review investment and reporting terms","description":"Before acceptance, review instrument, dilution, milestones, governance, disbursement and reporting obligations.","url":"https://tribal.gov.in/PFMS_SentionDtSchemewise2627.aspx"}],"window_type":"rolling","window_close_at":null,"window_label":"Fund/call availability requires current IFCI VCF and Ministry confirmation; no open nationwide founder deadline is established by the reviewed overview.","window_evidence":{"source_url":"https://tribal.gov.in/Livelihood.aspx","anchor":"Overview identifies the VCF-ST scheme and manager but does not state a current founder call deadline."},"review_note":"Keep review-gated and present as potential venture finance, never as a grant, fixed ticket or guaranteed investment."},
      {"slug":"nstfdc-term-loan-st-entrepreneurs","name":"NSTFDC Term Loan Scheme for Scheduled Tribe Entrepreneurs","type":"concessional_loan","status":"active","authority":"National Scheduled Tribes Finance and Development Corporation - Term Loan Scheme","authority_url":"https://nstfdc.tribal.gov.in/","canonical_url":"https://nstfdc.tribal.gov.in/","source_url":"https://nstfdc.tribal.gov.in/CuteSoft_Client/writereaddata/upload/NSTFDC_AR%20-%202024-25_Final_03-12-25_English.pdf","source_kind":"agency","source_title":"NSTFDC annual report 2024-25","source_anchor":"Term Loan Scheme: viable projects up to INR 50 lakh per unit, up to 90% project cost, ST eligibility and beneficiary interest bands","summary":"Concessional term finance for viable income-generating projects of Scheduled Tribe individuals, SHGs and eligible cooperatives through NSTFDC channelising routes.","objective":"Enable ST entrepreneurs and groups to establish or expand viable income-generating activities.","legal_basis":"NSTFDC official annual report and scheme reference material; current channelising-agency terms, income rules and lending policy control the live case.","eligibility":{"entity_types":["st_individual","st_self_help_group","st_cooperative","micro_business","small_business"],"lifecycle_stages":["starting","operating","expanding"],"industries":["manufacturing","services","retail","transport","agriculture_and_allied","artisan","rural_enterprise"],"locations":["India","rural_area","urban_area"],"conditions":["applicant or required share of cooperative membership must belong to the Scheduled Tribes community","project must be viable and income-generating","application is routed through an NSTFDC State Channelising Agency or approved partner","project cost, finance share, promoter contribution/subsidy, income ceiling and beneficiary rate must be reconciled against the current scheme","security, repayment and monitoring terms are determined under the current appraisal"],"thresholds":{"project_cost_max_inr":5000000,"nstfdc_finance_share_max_percent":90,"annual_family_income_reference_inr":300000,"higher_income_rate_band_reference_inr":600000,"beneficiary_interest_bands_percent":[6,8,10]},"unknown_handling":"needs_information"},"exclusions":["project cost is not the same as guaranteed loan amount","the 90% share must not be displayed as an automatic sanction","historical NSTFDC references contain differing ceilings and income bands","subsidy, margin money, collateral and repayment terms require current SCA confirmation","UdyamVeda cannot approve or disburse NSTFDC finance"],"application":{"portal":"https://nstfdc.tribal.gov.in/","route":"Contact the relevant State Channelising Agency or approved NSTFDC partner, prepare the viable project and ST/income/KYC evidence, and complete its appraisal route.","selection":"The SCA/NSTFDC/partner evaluates viability, project cost, contribution, security, repayment and eligibility; UdyamVeda cannot guarantee approval.","fees":"No universal applicant fee is established by the reviewed material; SCA/bank processing and documentation terms must be confirmed.","applicant_note":"UdyamVeda may prepare and validate a checklist, but must not impersonate the applicant, collect OTPs or file in place of the SCA/applicant."},"fine_print":{"project_boundary":"The current annual report describes viable projects up to INR 50 lakh per unit and NSTFDC assistance up to 90% of project cost; this is not a guaranteed loan ceiling.","income_and_rates":"The annual report describes a general family-income reference of INR 3 lakh and a higher-income rate band up to INR 6 lakh, with beneficiary rates depending on assistance band; current policy must control.","route":"Applicants should approach the district office of an NSTFDC State Channelising Agency or the currently listed partner route.","review_note":"Human review must reconcile the annual report, current portal, lending policy, SCA list, income thresholds, interest bands, contribution, collateral, repayment, documents and amendments before publication."},"benefit_summary":{"types":["loan"],"summary":"Concessional term finance for viable ST income-generating projects, with a current published project-cost reference up to INR 50 lakh and finance share up to 90%, subject to appraisal and SCA terms.","separate_value_buckets":true},"benefit_type":"loan","benefit_label":"NSTFDC term finance: project cost up to INR 50 lakh and finance share up to 90% subject to current SCA appraisal","amount_min":null,"amount_max":null,"percentage":90,"benefit_conditions":{"project_cost_max_inr":5000000,"finance_share_max_percent":90,"st_status_required":true,"sca_route_required":true,"loan_not_guaranteed":true},"requirement":"ST certificate, income/KYC/residence records, viable project report and SCA forms","requirement_description":"Provide ST certificate, income certificate, identity/address/KYC, project report, quotations, promoter contribution or margin evidence, bank records, security documents and current SCA forms.","rules":{"all":[{"field":"scheduled_tribe_status_verified","operator":"equals","value":true},{"field":"viable_income_generating_project_verified","operator":"equals","value":true},{"field":"nstfdc_sca_route_available","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Confirm current NSTFDC product and SCA","description":"Select the current term-loan route and confirm the State Channelising Agency or approved partner serving the applicant.","url":"https://nstfdc.tribal.gov.in/"},{"title":"Prepare project and ST evidence","description":"Collect project viability, cost, ST, income, KYC, contribution and security records.","url":"https://nstfdc.tribal.gov.in/CuteSoft_Client/writereaddata/upload/NSTFDC_AR%20-%202024-25_Final_03-12-25_English.pdf"},{"title":"Submit through the SCA/partner","description":"File through the authorized channel and complete appraisal, sanction and documentation.","url":"https://nstfdc.tribal.gov.in/"},{"title":"Confirm disbursement and repayment","description":"Review final finance share, interest, contribution, security, moratorium, repayment and monitoring terms before acceptance.","url":"https://nstfdc.tribal.gov.in/UploadData/pdf/RTI_English_16-06-21_NSTFDC.pdf"}],"window_type":"rolling","window_close_at":null,"window_label":"Rolling channel-finance route; local SCA capacity and current policy must be confirmed.","window_evidence":{"source_url":"https://nstfdc.tribal.gov.in/","anchor":"Official NSTFDC portal provides a standing scheme/channel-partner route rather than one nationwide closing date."},"review_note":"Keep review-gated. Display project cost and finance share separately; never calculate them as a guaranteed sanctioned amount."},
      {"slug":"nstfdc-trifed-empanelled-artisan-credit","name":"NSTFDC Assistance for TRIFED-empanelled Tribal Artisans","type":"artisan_credit","status":"active","authority":"National Scheduled Tribes Finance and Development Corporation - TRIFED Empanelled Artisan Assistance","authority_url":"https://nstfdc.tribal.gov.in/","canonical_url":"https://trifed.tribal.gov.in/en/node/950","source_url":"https://nstfdc.tribal.gov.in/CuteSoft_Client/writereaddata/upload/NSTFDC_AR%20-%202024-25_Final_03-12-25_English.pdf","source_kind":"agency","source_title":"NSTFDC annual report 2024-25","source_anchor":"Special scheme for TRIFED-empanelled artisans: project assets and working capital, individual/SHG ceilings and interest concessions","summary":"Concessional assistance for project assets and working capital of tribal artisans empanelled with TRIFED, including individual and group routes.","objective":"Improve productive capacity and market participation of TRIFED-empanelled tribal artisans through asset and working-capital finance.","legal_basis":"NSTFDC official scheme material and TRIFED empanelment page; current empanelment, SCA and lending terms control the live case.","eligibility":{"entity_types":["trifed_empanelled_artisan","tribal_artisan_shg","tribal_artisan_cooperative"],"lifecycle_stages":["starting","operating","expanding"],"industries":["handicrafts","handloom","tribal_products","traditional_occupations","artisan_manufacturing"],"locations":["India","rural_area","urban_area"],"conditions":["applicant must be a Scheduled Tribe artisan or eligible group","individual or group must satisfy the current TRIFED empanelment condition","finance is for project-related assets and working capital","individual and SHG/cooperative ceilings are separate and must not be combined","current SCA, contribution, rate and repayment terms require confirmation"],"thresholds":{"individual_assistance_max_inr":50000,"shg_or_cooperative_assistance_max_inr":500000,"finance_share_max_percent":90,"beneficiary_interest_percent_male":6,"beneficiary_interest_percent_women":4},"unknown_handling":"needs_information"},"exclusions":["TRIFED registration or empanelment is not the same as guaranteed credit","individual and group ceilings are separate","the route is not a universal grant or free equipment entitlement","current artisan, SCA and repayment conditions must be verified","marketing/empanelment and credit are separate supports"],"application":{"portal":"https://trifed.tribal.gov.in/en/node/950","route":"Confirm TRIFED empanelment, prepare the asset/working-capital plan and apply through the applicable NSTFDC State Channelising Agency or partner.","selection":"TRIFED and/or the SCA/partner verifies artisan status, group route, project need, documentation and repayment; UdyamVeda cannot approve the assistance.","fees":"No universal applicant fee is established by the reviewed sources; current empanelment and SCA terms must be confirmed.","applicant_note":"UdyamVeda may explain the separate empanelment and credit checklists but must not impersonate TRIFED or NSTFDC."},"fine_print":{"route":"TRIFED empanelment provides a market/sourcing route; NSTFDC assistance is a separate finance appraisal.","ceilings":"The official NSTFDC reference describes up to INR 50,000 for an individual and up to INR 5 lakh for an SHG/cooperative, with up to 90% finance share; show buckets separately.","rate":"The reference describes beneficiary rates of 6% for men and 4% for women for the special artisan scheme; current lending policy and channel terms must be reconciled.","review_note":"Human review must verify current TRIFED empanelment form, artisan definition, group route, ceilings, finance share, rates, contribution, documents, repayment and amendments before publication."},"benefit_summary":{"types":["loan","market_access"],"summary":"Separate individual and group artisan-credit routes linked to TRIFED empanelment, with a market/sourcing pathway and current finance values requiring SCA confirmation.","separate_value_buckets":true},"benefit_type":"loan","benefit_label":"NSTFDC artisan credit: up to INR 50,000 individual or INR 5 lakh group route, subject to TRIFED empanelment and SCA terms","amount_min":null,"amount_max":500000,"percentage":90,"benefit_conditions":{"trifed_empanelment_required":true,"individual_max_inr":50000,"group_max_inr":500000,"finance_share_max_percent":90,"loan_not_guaranteed":true},"requirement":"ST/artisan proof, TRIFED empanelment, asset or working-capital plan and current SCA documents","requirement_description":"Provide ST and artisan activity evidence, TRIFED empanelment records, group/cooperative documents if applicable, asset quotations, working-capital plan, KYC, contribution and SCA forms.","rules":{"all":[{"field":"scheduled_tribe_artisan_verified","operator":"equals","value":true},{"field":"trifed_empanelment_verified","operator":"equals","value":true},{"field":"artisan_credit_route_available","operator":"equals","value":true}],"unknown_handling":"needs_information"},"steps":[{"title":"Confirm TRIFED empanelment","description":"Check the current artisan/SHG/producer empanelment route and retain the submitted or approved record.","url":"https://trifed.tribal.gov.in/en/node/950"},{"title":"Prepare asset and working-capital evidence","description":"Document the craft activity, quotations, working-capital need, group structure and contribution.","url":"https://nstfdc.tribal.gov.in/CuteSoft_Client/writereaddata/upload/NSTFDC_AR%20-%202024-25_Final_03-12-25_English.pdf"},{"title":"Apply through the NSTFDC channel","description":"Submit through the relevant State Channelising Agency or approved partner and complete appraisal.","url":"https://nstfdc.tribal.gov.in/"},{"title":"Confirm separate individual/group terms","description":"Review the final ceiling, finance share, rate, repayment, security and monitoring obligations.","url":"https://nstfdc.tribal.gov.in/UploadData/pdf/RTI_English_16-06-21_NSTFDC.pdf"}],"window_type":"rolling","window_close_at":null,"window_label":"Rolling empanelment and channel-finance route; current TRIFED/SCA availability must be confirmed.","window_evidence":{"source_url":"https://trifed.tribal.gov.in/en/node/950","anchor":"Current TRIFED page describes ongoing empanelment and supplier registration, but does not establish a single nationwide credit deadline."},"review_note":"Keep review-gated. Never combine the individual and group ceilings or imply that TRIFED empanelment guarantees finance."}
    ]$records$::jsonb)
  loop
    authority_id := null;
    insert into public.authorities (name, level, ministry, department, official_url)
    select item->>'authority', 'central', 'Ministry of Tribal Affairs', 'Livelihood and implementing agencies', item->>'authority_url'
    where not exists (select 1 from public.authorities where name = item->>'authority')
    returning id into authority_id;
    if authority_id is null then select id into authority_id from public.authorities where name = item->>'authority' limit 1; end if;
    seed_opportunity_id := null;
    insert into public.opportunities (slug, name, opportunity_type, status, authority_id, geography, canonical_url)
    values (item->>'slug', item->>'name', item->>'type', item->>'status', authority_id, '{"coverage":"central","locations":["India"]}'::jsonb, item->>'canonical_url')
    on conflict (slug) do update set name = excluded.name, status = excluded.status, authority_id = excluded.authority_id, canonical_url = excluded.canonical_url
    returning id into seed_opportunity_id;
    if seed_opportunity_id is null then select id into seed_opportunity_id from public.opportunities where slug = item->>'slug' limit 1; end if;
    version_id := null;
    insert into public.opportunity_versions
      (opportunity_id, version_number, title, summary, objective, legal_basis, eligibility, application, fine_print, benefit_summary, last_verified_at, completeness, confidence, review_status)
    values (seed_opportunity_id, 1, item->>'name', item->>'summary', item->>'objective', item->>'legal_basis', item->'eligibility', item->'application', item->'fine_print', item->'benefit_summary', now(), 0.88, 0.82, 'in_review')
    on conflict (opportunity_id, version_number) do nothing
    returning id into version_id;
    if version_id is null then select ov.id into version_id from public.opportunity_versions ov where ov.opportunity_id = seed_opportunity_id and ov.version_number = 1 limit 1; end if;
    update public.opportunities set current_version_id = version_id, status = item->>'status' where id = seed_opportunity_id;
    insert into public.opportunity_sources (opportunity_version_id, source_url, source_kind, source_title, source_anchor, fetched_at, is_primary)
    values
      (version_id, item->>'source_url', item->>'source_kind', item->>'source_title', item->>'source_anchor', now(), true),
      (version_id, 'https://tribal.gov.in/Livelihood.aspx', 'ministry', 'Ministry of Tribal Affairs livelihood schemes', 'PMJVM, VCF-ST and livelihood route overview', now(), false),
      (version_id, 'https://tribal.gov.in/PFMS_SentionDtSchemewise2627.aspx', 'ministry', 'Ministry of Tribal Affairs FY 2026-27 financial summary', 'Current-year allocation and sanction boundary', now(), false),
      (version_id, 'https://trifed.tribal.gov.in/index.php/en/pmvdy', 'agency', 'TRIFED Van Dhan Yojana', 'VDVK and value-addition route', now(), false),
      (version_id, 'https://trifed.tribal.gov.in/en/node/950', 'agency', 'TRIFED artisan empanelment', 'Empanelment and supplier route', now(), false),
      (version_id, 'https://nstfdc.tribal.gov.in/', 'agency', 'NSTFDC official portal', 'Channelising-agency and current scheme route', now(), false),
      (version_id, 'https://nstfdc.tribal.gov.in/CuteSoft_Client/writereaddata/upload/NSTFDC_AR%20-%202024-25_Final_03-12-25_English.pdf', 'annual_report', 'NSTFDC annual report 2024-25', 'Scheme and lending boundaries', now(), false)
    on conflict do nothing;
    insert into public.opportunity_benefits (opportunity_version_id, benefit_type, label, amount_min, amount_max, percentage, conditions)
    select version_id, item->>'benefit_type', item->>'benefit_label', (item->>'amount_min')::numeric, (item->>'amount_max')::numeric, (item->>'percentage')::numeric, item->'benefit_conditions'
    where not exists (select 1 from public.opportunity_benefits where opportunity_version_id = version_id and label = item->>'benefit_label');
    insert into public.opportunity_requirements (opportunity_version_id, requirement_type, name, description, required)
    select version_id, 'document', item->>'requirement', item->>'requirement_description', true
    where not exists (select 1 from public.opportunity_requirements where opportunity_version_id = version_id and name = item->>'requirement');
    insert into public.eligibility_rule_sets (opportunity_version_id, rules, source_evidence, reviewed)
    select version_id, item->'rules', jsonb_build_array(jsonb_build_object('source_url', item->>'source_url', 'anchor', item->>'source_anchor')), false
    where not exists (select 1 from public.eligibility_rule_sets where opportunity_version_id = version_id);
    insert into public.opportunity_steps (opportunity_version_id, step_number, title, description, official_url)
    select version_id, row_number() over ()::integer, step->>'title', step->>'description', step->>'url'
    from jsonb_array_elements(item->'steps') as steps(step)
    where not exists (select 1 from public.opportunity_steps where opportunity_version_id = version_id);
    insert into public.opportunity_windows (opportunity_version_id, window_type, closes_at, label, source_evidence)
    select version_id, item->>'window_type', (item->>'window_close_at')::timestamptz, item->>'window_label', item->'window_evidence'
    where not exists (select 1 from public.opportunity_windows where opportunity_version_id = version_id);
    insert into public.review_tasks (opportunity_version_id, task_type, status)
    select version_id, 'publish', 'open'
    where not exists (select 1 from public.review_tasks where opportunity_version_id = version_id and task_type = 'publish' and status in ('open', 'in_review'));
  end loop;
end $$;

-- Correct the artisan draft on clean local provisioning as well as through
-- the later reconciliation migration. The annual-report citation is retained
-- only as supporting context, not as the artisan-specific controlling source.
do $$
declare
  artisan_version_id uuid;
begin
  select current_version_id into artisan_version_id
  from public.opportunities
  where slug = 'nstfdc-trifed-empanelled-artisan-credit';

  if artisan_version_id is not null then
    update public.opportunity_sources
    set
      source_url = 'https://nstfdc.tribal.gov.in/UploadData/pdf/RTI.pdf',
      source_kind = 'guideline',
      source_title = 'NSTFDC RTI Manual No. 4',
      source_anchor = 'Manual No. 4: Assistance to TRIFED empanelled Artisans and special-scheme lending norms',
      is_primary = true
    where opportunity_version_id = artisan_version_id
      and is_primary = true;

    update public.opportunity_steps
    set official_url = 'https://nstfdc.tribal.gov.in/UploadData/pdf/RTI.pdf'
    where opportunity_version_id = artisan_version_id
      and official_url = 'https://nstfdc.tribal.gov.in/CuteSoft_Client/writereaddata/upload/NSTFDC_AR%20-%202024-25_Final_03-12-25_English.pdf';

    update public.eligibility_rule_sets
    set source_evidence = jsonb_build_array(jsonb_build_object(
      'source_url', 'https://nstfdc.tribal.gov.in/UploadData/pdf/RTI.pdf',
      'anchor', 'Manual No. 4: Assistance to TRIFED empanelled Artisans and special-scheme lending norms'
    ))
    where opportunity_version_id = artisan_version_id;
  end if;
end $$;
